#include <vector>
#include <cstddef>
#include <cmath>
#include <algorithm>
#include <omp.h>

struct COOElement {
   size_t row, column;
   double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use OpenMP to compute in parallel.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    x.assign(N, 0.0);
    if (N == 0) return;

    // Build a dense augmented matrix [A | b].
    // Parallelize safely by assigning each COO entry to a unique iteration and using atomic
    // in case COO contains duplicate coordinates.
    std::vector<double> aug(N * (N + 1), 0.0);

    #pragma omp parallel for schedule(static)
    for (size_t i = 0; i < A.size(); ++i) {
        const size_t r = A[i].row;
        const size_t c = A[i].column;
        if (r < N && c < N) {
            #pragma omp atomic update
            aug[r * (N + 1) + c] += A[i].value;
        }
    }

    #pragma omp parallel for schedule(static)
    for (size_t i = 0; i < N; ++i) {
        aug[i * (N + 1) + N] = (i < b.size() ? b[i] : 0.0);
    }

    const double eps = 1e-12;

    // Gaussian elimination with partial pivoting.
    for (size_t k = 0; k < N; ++k) {
        // Find pivot row sequentially for determinism and simplicity.
        size_t pivot = k;
        double maxAbs = std::fabs(aug[k * (N + 1) + k]);
        for (size_t i = k + 1; i < N; ++i) {
            const double v = std::fabs(aug[i * (N + 1) + k]);
            if (v > maxAbs) {
                maxAbs = v;
                pivot = i;
            }
        }

        if (maxAbs <= eps) {
            // Singular or nearly singular system; leave x as zeros.
            return;
        }

        if (pivot != k) {
            #pragma omp parallel for schedule(static)
            for (size_t j = k; j <= N; ++j) {
                std::swap(aug[k * (N + 1) + j], aug[pivot * (N + 1) + j]);
            }
        }

        const double pivotVal = aug[k * (N + 1) + k];

        // Eliminate rows below pivot. Each thread updates a distinct row.
        #pragma omp parallel for schedule(static)
        for (size_t i = k + 1; i < N; ++i) {
            const double factor = aug[i * (N + 1) + k] / pivotVal;
            aug[i * (N + 1) + k] = 0.0;
            for (size_t j = k + 1; j <= N; ++j) {
                aug[i * (N + 1) + j] -= factor * aug[k * (N + 1) + j];
            }
        }
    }

    // Back substitution.
    for (ptrdiff_t i = static_cast<ptrdiff_t>(N) - 1; i >= 0; --i) {
        double sum = 0.0;

        #pragma omp parallel for reduction(+:sum) schedule(static)
        for (ptrdiff_t j = i + 1; j < static_cast<ptrdiff_t>(N); ++j) {
            sum += aug[static_cast<size_t>(i) * (N + 1) + static_cast<size_t>(j)] * x[static_cast<size_t>(j)];
        }

        const double diag = aug[static_cast<size_t>(i) * (N + 1) + static_cast<size_t>(i)];
        if (std::fabs(diag) <= eps) {
            x.assign(N, 0.0);
            return;
        }
        x[static_cast<size_t>(i)] = (aug[static_cast<size_t>(i) * (N + 1) + N] - sum) / diag;
    }
}
